export function meshReport(faces){const edges=new Map(),key=p=>p.map(n=>n.toFixed(6)).join(','),vertices=new Set();let volume=0;for(const [a,b,c] of faces){volume+=(a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0]))/6;for(const [u,v] of [[a,b],[b,c],[c,a]]){const x=key(u),y=key(v);vertices.add(x);vertices.add(y);const e=x<y?x+'|'+y:y+'|'+x,old=edges.get(e)||{count:0,direction:0};old.count++;old.direction+=x<y?1:-1;edges.set(e,old);}}return {triangles:faces.length,vertices:vertices.size,volume,badEdges:[...edges.values()].filter(e=>e.count!==2||e.direction!==0).length};}
export function buildSTL(data){const faces=buildFoamMesh(data),report=meshReport(faces);if(report.badEdges||report.volume<=0)throw Error('Could not make a closed STL for this layout. Use SVG/DXF or simplify overlapping depth regions.');const buffer=new ArrayBuffer(84+faces.length*50),view=new DataView(buffer),header=new TextEncoder().encode('Toolnest foam solid; units mm; XY bottom-left; Z bottom=0');new Uint8Array(buffer,0,Math.min(80,header.length)).set(header.slice(0,80));view.setUint32(80,faces.length,true);let offset=84;for(const [a,b,c] of faces){const u=b.map((n,i)=>n-a[i]),v=c.map((n,i)=>n-a[i]),normal=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]],len=Math.hypot(...normal)||1;for(const p of [normal.map(n=>n/len),a,b,c])for(const n of p){view.setFloat32(offset,n,true);offset+=4;}view.setUint16(offset,0,true);offset+=2;}return buffer;}
